#include <stdio.h>

int main(void) {
  int completed, total;
  if (scanf("%d %d", &completed, &total) != 2 || total == 0) return 1;
  double percent = (double)completed * 100.0 / total;
  printf("percent=%.1f%%\n", percent);
  return 0;
}
